import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"快捷键与交互手势","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 全局快捷键速查表","slug":"_1-全局快捷键速查表","link":"#_1-全局快捷键速查表","children":[{"level":3,"title":"文件对话框中的空查询","slug":"文件对话框中的空查询","link":"#文件对话框中的空查询","children":[]},{"level":3,"title":"内嵌窗口的呼出与焦点交接","slug":"内嵌窗口的呼出与焦点交接","link":"#内嵌窗口的呼出与焦点交接","children":[]}]},{"level":2,"title":"2. 搜索框图标与鼠标手势","slug":"_2-搜索框图标与鼠标手势","link":"#_2-搜索框图标与鼠标手势","children":[{"level":3,"title":"快速搜索窗口中的图标手势","slug":"快速搜索窗口中的图标手势","link":"#快速搜索窗口中的图标手势","children":[]},{"level":3,"title":"内嵌窗口与主窗口中的图标","slug":"内嵌窗口与主窗口中的图标","link":"#内嵌窗口与主窗口中的图标","children":[]},{"level":3,"title":"搜索框手势（快速窗口）","slug":"搜索框手势-快速窗口","link":"#搜索框手势-快速窗口","children":[]},{"level":3,"title":"系统托盘图标","slug":"系统托盘图标","link":"#系统托盘图标","children":[]}]},{"level":2,"title":"3. 快速导航（鼠标触发）","slug":"_3-快速导航-鼠标触发","link":"#_3-快速导航-鼠标触发","children":[{"level":3,"title":"触发方式与支持环境","slug":"触发方式与支持环境","link":"#触发方式与支持环境","children":[]},{"level":3,"title":"级联菜单内容与管理","slug":"级联菜单内容与管理","link":"#级联菜单内容与管理","children":[]}]},{"level":2,"title":"4. 硬编码核心按键（不可修改）","slug":"_4-硬编码核心按键-不可修改","link":"#_4-硬编码核心按键-不可修改","children":[]},{"level":2,"title":"5. 插件动作快捷键与进程黑名单","slug":"_5-插件动作快捷键与进程黑名单","link":"#_5-插件动作快捷键与进程黑名单","children":[{"level":3,"title":"插件独立动作快捷键","slug":"插件独立动作快捷键","link":"#插件独立动作快捷键","children":[]},{"level":3,"title":"进程黑名单与全屏自动放行","slug":"进程黑名单与全屏自动放行","link":"#进程黑名单与全屏自动放行","children":[]}]}],"relativePath":"zh-CN/user-guide/hotkeys.md","filePath":"zh-CN/user-guide/hotkeys.md","lastUpdated":1791112464000}`),a={name:`zh-CN/user-guide/hotkeys.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="快捷键与交互手势" tabindex="-1">快捷键与交互手势 <a class="header-anchor" href="#快捷键与交互手势" aria-label="Permalink to “快捷键与交互手势”">​</a></h1><p>Lertaro 采用键盘优先的交互设计，同时提供多种鼠标快捷手势与多级导航系统。除固定按键外，所有全局与应用内快捷键均可在<a href="./settings/hotkeys-page.html"><strong>设置 → 快捷键</strong></a>中自由重新绑定。</p><h2 id="_1-全局快捷键速查表" tabindex="-1">1. 全局快捷键速查表 <a class="header-anchor" href="#_1-全局快捷键速查表" aria-label="Permalink to “1. 全局快捷键速查表”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">功能动作</th><th style="text-align:left;">默认快捷键</th><th style="text-align:left;">功能说明与交互细节</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>呼出/隐藏快速窗口</strong></td><td style="text-align:left;">双击 <code>Ctrl</code></td><td style="text-align:left;">可设置为双击模式或常规组合键（例如 <code>Alt+Space</code> 等）。双击是指<strong>同一个</strong>修饰键被连续按下两次、且两次释放相隔 <strong>100–300 毫秒</strong>，左 <code>Ctrl</code> 与右 <code>Ctrl</code> 是两个不同的按键，期间按下任何其他键都会让计数重新开始。双击模式下修饰键本身绝不会被吞掉，因此普通的 <code>Ctrl</code>+<code>C</code> 之类快捷键照常生效。启用“默认打开完整面板”后，该快捷键会改为打开完整窗口：首次显示时只将其置于前台并聚焦一次，窗口已显示但未激活时重新激活，窗口已经激活时再次按下则默认切回快速窗口，开启“再次按下快捷键时关闭完整窗口”后则直接关闭；窗口不会自动保持置顶。</td></tr><tr><td style="text-align:left;"><strong>快速切换（Quick Jump）</strong></td><td style="text-align:left;"><code>Ctrl+G</code></td><td style="text-align:left;">在文件对话框中直接跳转到最近一次在资源管理器、受支持的文件管理器或文件对话框中浏览的文件夹。</td></tr><tr><td style="text-align:left;"><strong>快速导航菜单</strong></td><td style="text-align:left;">无默认快捷键</td><td style="text-align:left;">可选的全局快捷键，用于打开级联式快速导航菜单。在桌面或普通应用中呼出时使用桌面上下文；在文件资源管理器和原生文件对话框中呼出时使用当前窗口上下文。即使普通前台保护会抑制全局快捷键，文件管理器和文件对话框仍会放行。</td></tr><tr><td style="text-align:left;"><strong>选中下一项</strong></td><td style="text-align:left;"><code>Ctrl+N</code> 或 <code>↓</code></td><td style="text-align:left;">向下移动列表高亮项。在快速面板中支持跨分组连续浏览；在快速启动面板中，方向键按照可见网格移动，左右键按阅读顺序跨越行边界，上下键保持当前列只在相邻行之间移动，目标行该列没有项目时保持当前位置；快速启动面板显示且搜索内容为空时，<code>Ctrl+N</code> 会循环切换到下一个数据源。</td></tr><tr><td style="text-align:left;"><strong>选中上一项</strong></td><td style="text-align:left;"><code>Ctrl+P</code> 或 <code>↑</code></td><td style="text-align:left;">向上移动列表高亮项。在快速面板中同样支持跨分组遍历；在快速启动面板中，方向键按照可见网格移动，左右键按阅读顺序跨越行边界，上下键保持当前列只在相邻行之间移动，目标行该列没有项目时保持当前位置；快速启动面板显示且搜索内容为空时，<code>Ctrl+P</code> 会循环切换到上一个数据源。</td></tr><tr><td style="text-align:left;"><strong>跳转至第 1–9 项结果</strong></td><td style="text-align:left;"><code>Ctrl</code> + <code>1</code>–<code>9</code></td><td style="text-align:left;">修饰键可自定义，快速窗口结果旁会显示对应的数字徽章，直接按键打开目标项。数字指的是<strong>从首个可见行算起</strong>的第 N 个可选中项目，因此滚动列表时徽章会随之重新编号；<code>0</code> 未绑定。唯一的例外是起始页，它为磁贴绑定 <code>1</code>–<code>9</code>、<code>0</code> 与 <code>A</code>–<code>Z</code>，最多 36 个磁贴。</td></tr><tr><td style="text-align:left;"><strong>打开动作菜单</strong></td><td style="text-align:left;"><code>Ctrl+O</code> 或 <code>→</code></td><td style="text-align:left;">展开选中结果的上下文动作面板（复制路径、属性、管理员运行、文件操作等）。快速窗口和文件对话框<strong>之外</strong>的内嵌卡片都能用它；完整窗口改用鼠标右键或 <code>Apps</code> 键（<code>Shift+F10</code>）打开同一个菜单。</td></tr><tr><td style="text-align:left;"><strong>从选中项补全搜索词</strong></td><td style="text-align:left;"><code>Ctrl+Tab</code></td><td style="text-align:left;">将当前选中项的名称或完整路径直接填入搜索框，便于在此基础上做二次筛选。</td></tr><tr><td style="text-align:left;"><strong>QuickLook 即时预览</strong></td><td style="text-align:left;"><code>Alt+P</code></td><td style="text-align:left;">开启/关闭选中项的侧边预览面板（图片、文档、音视频即时播放、文件夹结构等）。快速窗口、完整窗口和快速面板均可用，内嵌卡片不支持；对可预览的行点击鼠标中键也能切换同一个面板。</td></tr><tr><td style="text-align:left;"><strong>上一条搜索历史词</strong></td><td style="text-align:left;"><code>Alt+Up</code></td><td style="text-align:left;">向前翻阅最近输入过的搜索关键词。</td></tr><tr><td style="text-align:left;"><strong>下一条搜索历史词</strong></td><td style="text-align:left;"><code>Alt+Down</code></td><td style="text-align:left;">向后翻阅最近输入过的搜索关键词。</td></tr><tr><td style="text-align:left;"><strong>删除当前历史词</strong></td><td style="text-align:left;"><code>Ctrl+Delete</code></td><td style="text-align:left;">从最近搜索历史记录中移除当前显示的这一条词汇。</td></tr><tr><td style="text-align:left;"><strong>打开完整搜索主窗口</strong></td><td style="text-align:left;"><code>Ctrl+F</code></td><td style="text-align:left;">直接打开大尺寸主搜索窗口，并自动同步当前快速窗口中的搜索词。</td></tr><tr><td style="text-align:left;"><strong>打开发送窗口（LocalSend）</strong></td><td style="text-align:left;"><code>Ctrl+S</code></td><td style="text-align:left;">打开 LocalSend 无线局域网传输窗口，快速发送文件或文本至跨平台设备。</td></tr><tr><td style="text-align:left;"><strong>保持窗口不消失（钉住）</strong></td><td style="text-align:left;"><code>Ctrl+T</code></td><td style="text-align:left;">临时锁定窗口，在失去焦点时不再自动隐藏（便于从其他窗口复制文字组合查询）。</td></tr><tr><td style="text-align:left;"><strong>呼出/关闭快速面板</strong></td><td style="text-align:left;"><code>Ctrl+F2</code></td><td style="text-align:left;">在当前前台活动窗口旁展开包含最近文件、收藏夹、工作区的快速停靠面板。</td></tr></tbody></table><h3 id="文件对话框中的空查询" tabindex="-1">文件对话框中的空查询 <a class="header-anchor" href="#文件对话框中的空查询" aria-label="Permalink to “文件对话框中的空查询”">​</a></h3><p>当内嵌搜索框位于原生文件对话框中且搜索内容为空时，列表会先显示“上一次目录”分组。开启“在内嵌搜索中显示当前打开的文件夹”后，还会显示汇总受支持文件管理器正在浏览目录的“当前打开的文件夹”分组，其中刻意包含对话框当前所在的目录；重复路径会自动去重，空分组不会显示，分组标题也不会显示快捷键徽章。该开关默认开启，可在<a href="./settings/general.html"><strong>设置 → 通用 → 系统</strong></a>中修改。该行为只适用于文件对话框中的内嵌搜索，快速窗口和完整窗口不受影响。</p><h3 id="内嵌窗口的呼出与焦点交接" tabindex="-1">内嵌窗口的呼出与焦点交接 <a class="header-anchor" href="#内嵌窗口的呼出与焦点交接" aria-label="Permalink to “内嵌窗口的呼出与焦点交接”">​</a></h3><p>停靠在原生文件对话框中的卡片刻意<strong>不抢键盘</strong>：焦点留在对话框上，所以你继续在对话框自己的文件名输入框里打字，卡片只是同步显示同样的内容。真正移动光标的操作是：</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作</th><th style="text-align:left;">效果</th><th style="text-align:left;">生效条件</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>键入字母或数字</strong></td><td style="text-align:left;">呼出卡片，并把这第一个字符带进搜索框；之后的按键继续输入进去</td><td style="text-align:left;">只认真实按键，自动化工具合成的输入会原样放行；上下文菜单或系统菜单打开时不捕获任何按键</td></tr><tr><td style="text-align:left;"><strong>双击 <code>Ctrl</code></strong>（或你配置的呼出快捷键）</td><td style="text-align:left;">把光标定位到卡片自身的搜索框。若搜索框已持有光标且内容为空，则改为清空内容并把焦点交还给对话框的输入框，卡片保持打开</td><td style="text-align:left;">与各处用的是同一个快捷键，所以在<a href="./settings/hotkeys-page.html"><strong>设置 → 快捷键</strong></a>里改绑时这里也会跟着变。即使进程黑名单或全屏状态通常会让全局快捷键静默放行，文件对话框依然照常生效</td></tr><tr><td style="text-align:left;"><strong><code>Escape</code></strong></td><td style="text-align:left;"><strong>对话框</strong>持有键盘时关闭卡片；<strong>卡片</strong>持有键盘时清空内容并把焦点交还给对话框（文件对话框中），或关闭卡片（停靠在普通资源管理器窗口上时）</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>搜索框为空时按 <code>Backspace</code></strong></td><td style="text-align:left;">与 <code>Escape</code> 一样退出搜索</td><td style="text-align:left;">仅在卡片持有光标时；焦点在对话框一侧时，该键只是编辑卡片的搜索内容</td></tr><tr><td style="text-align:left;"><strong>搜索框为空时按 <code>Enter</code></strong></td><td style="text-align:left;">与 <code>Escape</code> 一样退出搜索</td><td style="text-align:left;">仅在卡片持有光标时；焦点在对话框一侧时，<code>Enter</code> 打开高亮的浏览项</td></tr><tr><td style="text-align:left;"><strong><code>Tab</code></strong></td><td style="text-align:left;">始终留给对话框自身的控件遍历，因此请改用呼出快捷键进入卡片</td><td style="text-align:left;"></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>在文件对话框内，卡片没有动作菜单（<code>Ctrl+O</code>、<code>→</code> 和鼠标右键在那里都不起作用），也不提供 <code>Alt+P</code> 预览。鼠标在结果行上依然可用：<strong>左键单击</strong>打开高亮结果，<strong><code>Ctrl</code>+单击</strong>以管理员身份打开，结果行可以被<strong>拖出</strong>到对话框里，仅仅<strong>悬停</strong>即可移动选中项，宿主文件管理器会同步这一选择。</p></div><h2 id="_2-搜索框图标与鼠标手势" tabindex="-1">2. 搜索框图标与鼠标手势 <a class="header-anchor" href="#_2-搜索框图标与鼠标手势" aria-label="Permalink to “2. 搜索框图标与鼠标手势”">​</a></h2><p>搜索框内的小图标除了品牌标识，还集成了多种实用的鼠标快捷手势：</p><h3 id="快速搜索窗口中的图标手势" tabindex="-1">快速搜索窗口中的图标手势 <a class="header-anchor" href="#快速搜索窗口中的图标手势" aria-label="Permalink to “快速搜索窗口中的图标手势”">​</a></h3><ul><li><strong>鼠标左键单击</strong>：直接在光标处弹出快捷主菜单（显示主窗口、发送到其他设备、禁用/启用快捷键、设置、关于、干净退出、退出程序，与托盘菜单相同）。其中“显示主窗口”会自动携带当前输入的内容。</li><li><strong>鼠标左键按住拖动</strong>：自由拖动调整搜索栏在屏幕上的显示位置。<strong>拖动时按住 <code>Ctrl</code> 键</strong>可将移动方向严格锁定为<strong>纯垂直方向</strong>，避免水平位置发生偏移。</li><li><strong>鼠标右键单击</strong>：一键将快速窗口重置回屏幕初始默认居中位置（不改变已配置的窗口尺寸）。</li><li><strong>鼠标中键单击</strong>：快捷切换窗口“钉住（保持不消失）”状态，钉住期间 Logo 图标会高亮发光。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>快速窗口记录的屏幕坐标是相对于所在显示器的<strong>相对比例坐标</strong>。当你将窗口唤出在另一台不同分辨率、不同 DPI 缩放的显示器上时，Lertaro 会自动等比换算位置，绝不会跑出屏幕可视区域。</p></div><h3 id="内嵌窗口与主窗口中的图标" tabindex="-1">内嵌窗口与主窗口中的图标 <a class="header-anchor" href="#内嵌窗口与主窗口中的图标" aria-label="Permalink to “内嵌窗口与主窗口中的图标”">​</a></h3><ul><li><strong>内嵌窗口</strong>：当嵌入在原生文件对话框（打开/保存/浏览）时，左键点击图标可直接展开<a href="#_3-快速导航-鼠标触发"><strong>快速导航</strong></a>级联菜单；停靠在普通资源管理器时仅作展示。拖动图标会移动卡片本身，之后每次停靠都会重新套用这个偏移量。</li><li><strong>主窗口</strong>：鼠标左键点击图标会打开上下文菜单；由于完整窗口已经打开，菜单中的“显示主窗口”项目会隐藏。鼠标中键点击可切换窗口的置顶状态。</li></ul><h3 id="搜索框手势-快速窗口" tabindex="-1">搜索框手势（快速窗口） <a class="header-anchor" href="#搜索框手势-快速窗口" aria-label="Permalink to “搜索框手势（快速窗口）”">​</a></h3><ul><li><strong>在搜索框上滚动鼠标滚轮</strong>：向前/向后翻阅最近的搜索词，与 <code>Alt+Up</code> / <code>Alt+Down</code> 完全相同，手不必离开鼠标。</li><li><strong>在搜索框上点击鼠标中键</strong>：删除当前显示的这一条历史记录。该手势是硬编码的，并不是可配置的 <code>Ctrl+Delete</code> 绑定。</li><li><strong>任何时候开始打字</strong>都会结束本轮历史翻阅，因此下一格滚轮会重新从你当前的搜索内容出发。历史不会循环：翻到最旧一条就停在原地，最新一条则回到你最初输入的内容。</li></ul><h3 id="系统托盘图标" tabindex="-1">系统托盘图标 <a class="header-anchor" href="#系统托盘图标" aria-label="Permalink to “系统托盘图标”">​</a></h3><ul><li><strong>鼠标左键单击</strong>：切换快速窗口的显示与隐藏，和呼出快捷键的效果完全一致。</li><li><strong>鼠标右键单击</strong>（或再次单击，因为没有注册双击处理）：在光标处弹出菜单，包含显示主窗口、发送到其他设备（仅在 LocalSend 启用时出现）、禁用/启用快捷键、设置、关于、干净退出（仅在 Lertaro 是唯一运行进程时出现）、退出。</li><li><strong>隐藏托盘图标</strong>（<a href="./settings/general.html"><strong>设置 → 通用 → 系统</strong></a>）只去掉图标，绝不会去掉窗口内 Logo 的菜单。当你通过该菜单禁用快捷键时，托盘图标会被强制显示出来，免得把自己锁在门外。</li></ul><h2 id="_3-快速导航-鼠标触发" tabindex="-1">3. 快速导航（鼠标触发） <a class="header-anchor" href="#_3-快速导航-鼠标触发" aria-label="Permalink to “3. 快速导航（鼠标触发）”">​</a></h2><p>快速导航功能让你无需打字，通过鼠标点击即可在任意窗口中直达常用目录或打开文件。</p><p>你也可以在<a href="./settings/hotkeys-page.html"><strong>设置 → 快捷键</strong></a>中为快速导航菜单分配一个可选的全局快捷键。在桌面或普通应用中呼出时使用桌面上下文；在文件资源管理器和原生文件对话框中呼出时使用当前窗口上下文。</p><h3 id="触发方式与支持环境" tabindex="-1">触发方式与支持环境 <a class="header-anchor" href="#触发方式与支持环境" aria-label="Permalink to “触发方式与支持环境”">​</a></h3><ul><li><strong>桌面空白处</strong>：鼠标中键单击（或开启双击左键）直接弹出快速导航菜单，点击目录或文件直接打开。</li><li><strong>文件资源管理器</strong>：在资源管理器空白处点击鼠标中键触发，点击目标后当前窗口立即跳转到该路径。</li><li><strong>第三方文件管理器</strong>：在 Directory Opus、Total Commander、XYplorer、Files、One Commander 等工具的文件列表区点击鼠标中键触发（详见<a href="./file-manager-support.html"><strong>支持的文件管理器</strong></a>）。</li><li><strong>系统文件对话框</strong>：在任意软件的“打开/保存/浏览文件夹”对话框中点击中键或点击内嵌图标触发，点击后对话框直接跳转至目标目录，绝不会误触发“保存/打开”确认。</li></ul><h3 id="级联菜单内容与管理" tabindex="-1">级联菜单内容与管理 <a class="header-anchor" href="#级联菜单内容与管理" aria-label="Permalink to “级联菜单内容与管理”">​</a></h3><p>快速导航菜单由<strong>级联文件夹浏览器（Folder Cascader）</strong>插件驱动，内容分为四类：</p><ol><li><strong>当前打开的文件夹</strong>：自动汇总并去重所有受支持文件管理器当前正在浏览的真实目录，方便在不同应用间快速同步路径。</li><li><strong>收藏夹与历史记录</strong>：自动按分类列出你的加星收藏与最近访问历史。</li><li><strong>自定义快捷分类</strong>：支持在<strong>设置 → 插件 → 级联文件夹浏览器</strong>中自定义目录与子菜单（如使用 <code>工作/项目A</code> 创建多级分类）。</li><li><strong>一键添加目录（<code>+</code> 按钮）</strong>：菜单每个层级的标题右侧均设有一个 <code>+</code> 按钮，点击即可直接将当前正在浏览的文件夹快速保存到该分类下，无需打开设置面板。</li></ol><h2 id="_4-硬编码核心按键-不可修改" tabindex="-1">4. 硬编码核心按键（不可修改） <a class="header-anchor" href="#_4-硬编码核心按键-不可修改" aria-label="Permalink to “4. 硬编码核心按键（不可修改）”">​</a></h2><p>为了保证最核心交互的确定性与一致性，以下按键在任何配置下行为始终保持统一：</p><table tabindex="0"><thead><tr><th style="text-align:left;">按键</th><th style="text-align:left;">触发场景</th><th style="text-align:left;">统一行为</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">结果列表</td><td style="text-align:left;">直接打开选中的结果（文件/目录/程序/动作）。在完整窗口中会打开<strong>全部</strong>选中行。内嵌搜索框内容为空时则改为退出搜索，此时并没有可打开的首条结果。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">结果列表</td><td style="text-align:left;">在文件资源管理器中打开并定位选中项所在目录。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">结果列表</td><td style="text-align:left;">以管理员权限启动选中的程序或文件。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">快速窗口</td><td style="text-align:left;">隐藏窗口。这一次按键绝不会清空搜索框，内容是保留还是丢弃，改由<strong>关闭窗口后保留搜索框内容</strong>决定。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">完整窗口</td><td style="text-align:left;">清空搜索内容并让搜索框重新获得焦点；搜索框已为空时才关闭窗口，而开启<strong>关闭窗口后保留搜索框内容</strong>时第一次按下就直接关闭（不必白按两次）。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">内嵌卡片</td><td style="text-align:left;">参见上文的<strong>内嵌窗口的呼出与焦点交接</strong>：焦点在对话框一侧时关闭卡片，焦点在卡片一侧时交还焦点。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">动作菜单</td><td style="text-align:left;">一次按键退回一层：先清空动作过滤词，再退出子菜单，最后离开动作菜单并恢复原来的搜索内容。</td></tr><tr><td style="text-align:left;"><code>Backspace</code></td><td style="text-align:left;">动作菜单</td><td style="text-align:left;">当搜索过滤词已为空时，按下直接退出动作菜单返回结果列表。</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code> 方向键</td><td style="text-align:left;">动作菜单</td><td style="text-align:left;">左箭头返回上一级菜单，右箭头进入子菜单。<code>Tab</code> 同样能进入子菜单，除非你把它绑定到了上/下一项快捷键。</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">内嵌卡片</td><td style="text-align:left;">按键被吞掉，焦点无法离开搜索框；而对话框自身的 <code>Tab</code> 照旧遍历它自己的控件。</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">动作菜单</td><td style="text-align:left;">进入高亮的子菜单——除非你把 <code>Tab</code> 绑定为上/下一项快捷键，那样以绑定为准。</td></tr><tr><td style="text-align:left;"><code>Apps</code> / <code>Shift+F10</code></td><td style="text-align:left;">完整窗口</td><td style="text-align:left;">为当前选中项打开动作菜单，效果与鼠标右键完全一致。</td></tr><tr><td style="text-align:left;"><code>Alt+Space</code></td><td style="text-align:left;">所有 Lertaro 窗口</td><td style="text-align:left;">强制屏蔽系统标题栏菜单，防止误触弹窗。</td></tr><tr><td style="text-align:left;"><code>Alt+F4</code></td><td style="text-align:left;">主窗口 / 设置窗口</td><td style="text-align:left;">关闭当前窗口。在快速窗口、内嵌窗口、快速面板、预览浮窗、LocalSend 窗口以及应用内对话框上会被屏蔽（防止误关闭驻留服务）。</td></tr></tbody></table><h2 id="_5-插件动作快捷键与进程黑名单" tabindex="-1">5. 插件动作快捷键与进程黑名单 <a class="header-anchor" href="#_5-插件动作快捷键与进程黑名单" aria-label="Permalink to “5. 插件动作快捷键与进程黑名单”">​</a></h2><h3 id="插件独立动作快捷键" tabindex="-1">插件独立动作快捷键 <a class="header-anchor" href="#插件独立动作快捷键" aria-label="Permalink to “插件独立动作快捷键”">​</a></h3><p>内置文件动作的默认快捷键如下：剪切 <code>Ctrl+X</code>、复制文件 <code>Ctrl+C</code>、粘贴 <code>Ctrl+V</code>、删除 <code>Delete</code>、彻底删除 <code>Shift+Delete</code>、复制路径 <code>Ctrl+Shift+C</code>、复制名称 <code>Shift+C</code>、在资源管理器中定位 <code>Ctrl+Enter</code>、以管理员身份运行 <code>Ctrl+Shift+Enter</code>。</p><p>有两道保险让这些有破坏性的按键在搜索框之下依然安全。组合键只有在搜索框<strong>没有选中文本</strong>时才会触发动作，因此 <code>Ctrl+X</code> / <code>Ctrl+C</code> / <code>Ctrl+V</code> 照旧是剪切、复制和粘贴你的搜索内容。<code>Delete</code> 这类单独按键只有在光标<strong>已位于搜索内容末尾</strong>时才会触发动作，在那里它已经没有字符可删；处在文本其他任何位置时，它仍然是个打字按键。而且两个删除动作都走 Shell 自己的 <code>IFileOperation</code>，所以原生的“移入回收站？”/“彻底删除？”确认框仍然横亘在按键与文件之间。想改绑或清空其中任何一个，请到<strong>设置 → 快捷键 → 插件动作</strong>。</p><h3 id="进程黑名单与全屏自动放行" tabindex="-1">进程黑名单与全屏自动放行 <a class="header-anchor" href="#进程黑名单与全屏自动放行" aria-label="Permalink to “进程黑名单与全屏自动放行”">​</a></h3><ul><li><strong>全屏应用自动放行</strong>：当检测到前台有独占全屏运行的应用程序（如全屏 3D 游戏、全屏视频播放器）时，Lertaro 默认会自动放行所有全局快捷键，绝不抢占游戏控制。</li><li><strong>自定义进程黑名单</strong>：在<a href="./settings/hotkeys-page.html#_3-进程黑名单-process-blacklist"><strong>设置 → 快捷键页面</strong></a>中添加特定进程名（如 <code>game.exe</code>），当该程序处于前台时，全局快捷键与鼠标快速导航将完全静默放行。</li></ul>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};